INSERT INTO "AgentApproval" ("id","userId","threadId","toolName","capability","argsJson","description","status","decidedAt","createdAt") VALUES ('097e2ce1-33d6-4bd1-8071-e1db0b57f38b','cmusenqrl0000oir8zrgpm0p7','cb3d48a8-c2aa-4bb9-9f96-45bdd224be0a','generate_medical_illustration','media.image','{"prompt":"Simple educational illustration of a nephron showing the basic structure including glomerulus, Bowman''s capsule, proximal convoluted tubule, loop of Henle, distal convoluted tubule, and collecting duct. Include clear labels for each major component and show the direction of blood flow through the renal corpuscle. Clean, anatomically accurate design suitable for medical education."}','Generates a new medical illustration (uses image-generation quota). Prompt: Simple educational illustration of a nephron showing the basic structure including glomeru…','approved','2026-10-25T23:51:22.357Z','2026-10-25T23:51:22.348Z');
INSERT INTO "AgentApproval" ("id","userId","threadId","toolName","capability","argsJson","description","status","decidedAt","createdAt") VALUES ('33ae3cf8-e49a-4edd-ac8c-dc8511063b3f','cmusenqrl0000oir8zrgpm0p7','c877942c-d28e-4009-994b-d420e9296952','generate_medical_illustration','media.image','{"prompt":"Medical infographic comparing beta blockers and calcium physiology/therapy. Create a side-by-side comparison showing: 1) Beta blockers (classification, mechanisms, clinical uses, adverse effects) vs 2) Calcium (normal range, hypo/hyper manifestations, management). Use professional medical color scheme with clear sections, anatomical illustrations, and clinical correlations."}','Generates a new medical illustration (uses image-generation quota). Prompt: Medical infographic comparing beta blockers and calcium physiology/therapy. Create a side-…','rejected','2026-10-26T00:04:37.653Z','2026-10-26T00:04:37.653Z');

