INSERT INTO "AgentArtifact" ("id","userId","name","kind","mimeType","sizeBytes","content","url","meta","createdAt") VALUES ('cmvmuep28002oudrdtdt1ibgj','cmusenr950006oir80jr4ludo','medical-illustration-skill-package','markdown','text/markdown',1681,'# Medical Illustration Generator Skill

