','[{"id":"call_-7145200949034744086","name":"run_question_generation_agent","args":{"topic":"STEMI","system":"Cardiovascular","types":["mcq"],"difficulties":["Medium","Hard"],"count":5,"focusHint":"include an image with every question","useKnowledgeBase":true}},{"id":"call_-7145229673776019872","name":"task","args":{"description":"Generate exactly 5 medical questions on STEMI (ST-elevation myocardial infarction) for a cardiovascular medical system. Questions should be multiple choice (mcq) with mixed difficulty (Medium, Hard). Each question must include a medical image. The questions should cover key aspects of STEMI including pathophysiology, diagnosis, ECG findings, management, and complications. Include detailed explanations, clinical pearls, distractor analysis, and appropriate citations. Return the questions as a complete JSON array ready for saving.","subagent_type":"question-author"}},{"id":"search_medical_references-1-1792601412037","name":"search_medical_references","args":{"query":"STEMI ST-elevation myocardial infarction diagnosis management guidelines","maxResults":3}},{"id":"search_medical_references-2-1792601415067","name":"search_medical_references","args":{"query":"STEMI ECG findings ST segment elevation criteria","maxResults":2}},{"id":"search_medical_references-3-1792601417764","name":"search_medical_references","args":{"query":"STEMI complications cardiogenic shock ventricular arrhythmias","maxResults":2}},{"id":"generate_medical_illustration-4-1792601463098","name":"generate_medical_illustration","args":{"prompt":"Anatomically accurate educational illustration showing STEMI pathophysiology with coronary artery occlusion, myocardial infarction zone, ST segment elevation on ECG, and time-sensitive reperfusion therapy timeline. Include labeled coronary arteries, infarcted myocardium, ECG leads showing ST elevation, and clock indicating time to treatment."}},{"id":"generate_medical_illustration-5-1792601492737","name":"generate_medical_illustration"