INSERT INTO "AgentThreadMessage" ("id","threadId","role","content","toolCalls","toolResults","metadata","createdAt") VALUES ('cmvieo6o2002loku8ng2sx6im','ed9c7970-409e-4cf8-9b23-452cf03256a8','assistant','Here are heart anatomy image resources:

