INSERT INTO "AgentThreadMessage" ("id","threadId","role","content","toolCalls","toolResults","metadata","createdAt") VALUES ('cmvifco3t0003pyu8xvupb2eh','24db59cb-86f6-4778-ab8d-28d439647ec4','assistant','I''ll search for heart images for you using medical reference sources.

