INSERT INTO "AgentThreadMessage" ("id","threadId","role","content","toolCalls","toolResults","metadata","createdAt") VALUES ('cmvigrcqc0002fwu8ecahxkin','ee596281-bd27-447a-8d82-983b6871536c','assistant','I''ll search for heart anatomy image resources online for you.

