INSERT INTO "AgentThreadMessage" ("id","threadId","role","content","toolCalls","toolResults","metadata","createdAt") VALUES ('cmvm5gnf8000afqrd2j8gh0fe','1ae1cb15-b126-49a2-a86b-a2e05496215b','assistant','The **brachial plexus** is a network of nerves originating from spinal nerves C5-T8 that innervates the upper limb. It''s clinically significant because injuries can cause devastating loss of arm function, with the **upper trunk (C5-C6) being the most commonly injured** in traumatic events like motorcycle accidents or falls.',NULL,NULL,NULL,'2026-10-24T08:41:33.332Z');
