INSERT INTO "AgentToolExecution" ("id","userId","threadId","toolName","status","latencyMs","inputJson","outputJson","error","createdAt") VALUES ('cmvlz0d3q000mv6rdqan7vlo0','cmusenqrl0000oir8zrgpm0p7','228c86f9-7798-44b5-b9cf-a72f67403045','search_medical_references','completed',4134,'{"query":"first-line treatment anaphylaxis guidelines epinephrine","maxResults":5}','{"results":[{"title":"Emergency treatment of anaphylaxis: concise clinical guidance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9345203","snippet":"by AF Whyte · 2022 · Cited by 87 — IM adrenaline is the first-line treatment for anaphylaxis (Fig 2). There are no randomised trials evaluating adrenaline to treat anaphylaxis, however, extensive ... Read more","host":"pmc.ncbi.nlm.nih.gov","date":""},{"title":"Emergency treatment of anaphylaxis Guidelines for","url":"https://www.resus.org.uk/sites/default/files/2021-05/Emergency%20Treatment%20of%20Anaphylaxis%20May%202021_0.pdf","snippet":"Intramuscular adrenaline is the first-line treatment for anaphylaxis (even if intravenous access is available). • A single dose of IM adrenaline is well- ... Read more","host":"www.resus.org.uk","date":""},{"title":"Anaphylaxis: A 2023 practice parameter update","url":"https://www.aaaai.org/Aaaai/media/Media-Library-PDFs/Allergist%20Resources/Statements%20and%20Practice%20Parameters/Anaphylaxis-Practice-Paramaters-2023.pdf","snippet":"by DBK Golden · 2023 · Cited by 468 — Epinephrine is the first-line treatment for anaphylaxis , and EAIs allow patients to have this emergency medication available outside the medical setting.","host":"www.aaaai.org","date":""},{"title":"Anaphylaxis Clinical Pathway","url":"https://www.hopkinsmedicine.org/-/media/files/allchildrens/clinical-pathways/anaphylaxis-pathway-7_2023.pdf","snippet":"Intramuscular EPINEPHrine is the first line treatment for anaphylaxis (Class I, Level of Evidence A). EPINEPHrine has both alpha sympathomimetic and beta. ...","host":"www.hopkinsmedicine.org","dat