INSERT INTO "ChatMessage" ("id","roomId","senderId","content","type","metadata","isPinned","isDeleted","replyToId","editedAt","createdAt") VALUES ('cmusenrt40017otr8zffu50kg','cmusenrt00012otr84caymjkp','cmusenrpi0005otr83ayzy1fx','Amiodarone and warfarin — the interaction mechanism. Is it CYP inhibition?','text','{}',false,false,NULL,NULL,'2026-10-03T08:15:56.871Z');
INSERT INTO "ChatMessage" ("id","roomId","senderId","content","type","metadata","isPinned","isDeleted","replyToId","editedAt","createdAt") VALUES ('cmusenrt60018otr8sbiuty8i','cmusenrt00012otr84caymjkp','cmusenrnh0000otr801tx46cg','Exactly! Amiodarone inhibits CYP2C9 and CYP3A4, which metabolize warfarin. That''s why you need to reduce warfarin dose by 30-50%.','text','{}',false,false,NULL,NULL,'2026-10-03T08:20:56.874Z');
