INSERT INTO "ChatMessage" ("id","roomId","senderId","content","type","metadata","isPinned","isDeleted","replyToId","editedAt","createdAt") VALUES ('cmusenrul001uotr8amr2gyb1','cmusenrtm001hotr8fwkbubi9','cmusenrnp0001otr8k6w4z002','Quick question — what''s the mechanism behind digoxin toxicity causing hyperkalemia?','text','{}',false,false,NULL,NULL,'2026-10-03T10:05:56.925Z');
INSERT INTO "ChatMessage" ("id","roomId","senderId","content","type","metadata","isPinned","isDeleted","replyToId","editedAt","createdAt") VALUES ('cmusenrum001votr86sf5lb94','cmusenrtm001hotr8fwkbubi9','cmusenrnh0000otr801tx46cg','Digoxin inhibits the Na+/K+ ATPase pump. When it''s severely inhibited, K+ can''t enter cells → hyperkalemia. It''s also why hypokalemia increases dig toxicity — less K+ competing with digoxin for the pump binding site.','text','{}',false,false,NULL,NULL,'2026-10-03T10:15:56.926Z');
INSERT INTO "ChatMessage" ("id","roomId","senderId","content","type","metadata","isPinned","isDeleted","replyToId","editedAt","createdAt") VALUES ('cmusenrun001wotr8mgs2sidf','cmusenrtm001hotr8fwkbubi9','cmusenrpi0005otr83ayzy1fx','Great explanation! And that''s why we monitor potassium closely in patients on digoxin.','text','{}',false,false,'cmusenrum001votr86sf5lb94',NULL,'2026-10-03T10:20:56.927Z');
INSERT INTO "ChatMessage" ("id","roomId","senderId","content","type","metadata","isPinned","isDeleted","replyToId","editedAt","createdAt") VALUES ('cmusenruo001xotr8fdbhp9aw','cmusenrtm001hotr8fwkbubi9','cmusenron0002otr89cjp3s1v','🎤 Voice message (1:23)','text','{"isVoice":true,"duration":83,"audioUrl":"/uploads/voice/peds-cardio-case.webm"}',false,false,NULL,NULL,'2026-10-03T11:25:56.928Z');
