INSERT INTO "ClinicalCase" ("id","title","system","topic","difficulty","caseType","patientInfo","stages","isAIGenerated","createdAt","updatedAt") VALUES ('cmuser3j80046slr8o0ctep9b','Chest Pain in a 55-year-old Smoker','Cardiovascular','ACS','Moderate','diagnostic','{"age":55,"sex":"M","chiefComplaint":"Crushing chest pain for 1 hour","presentingHistory":"Smoker, HTN, family history CAD. Pain radiates to left arm, associated with diaphoresis."}','[{"question":"What is your initial differential diagnosis?","answer":"ACS (STEMI/NSTEMI/unstable angina), aortic dissection, PE, pericarditis"},{"question":"What is the first diagnostic test?","answer":"ECG within 10 minutes of arrival"},{"question":"ECG shows ST-elevation in II, III, aVF. What is the diagnosis?","answer":"Inferior STEMI"},{"question":"What is the most appropriate next step?","answer":"Immediate reperfusion — primary PCI within 90 min or tPA within 30 min"}]',false,'2026-10-03T13:08:32.036Z','2026-10-03T13:08:32.036Z');
INSERT INTO "ClinicalCase" ("id","title","system","topic","difficulty","caseType","patientInfo","stages","isAIGenerated","createdAt","updatedAt") VALUES ('cmuser3ja0047slr8abta1okh','Acute Dyspnea in a COPD Patient','Respiratory','COPD Exacerbation','Moderate','emergency','{"age":68,"sex":"F","chiefComplaint":"Increased dyspnea and purulent sputum","presentingHistory":"65-pack-year smoker, COPD on tiotropium. 3 days worsening dyspnea, yellow sputum, no fever."}','[{"question":"What are common triggers of COPD exacerbation?","answer":"Infection (viral/bacterial), environmental, non-adherence, PE"},{"question":"What is the initial workup?","answer":"CXR, ABG/VBG, CBC, BMP, troponin, ECG"},{"question":"What is the initial treatment?","answer":"SABA + ipratropium nebs, systemic steroids, antibiotics if purulent sputum"},{"question":"When is NIPPV (BiPAP) indicated?","answer":"pH <7.35 with PaCO2 >45 after initial therapy"}]',false,'2026-10-03T13:08:32.038Z','2026-10-03T13:08:32.038Z');
INSERT INTO "ClinicalCase" ("id","title","system","topic","difficulty","caseType","patientInfo","stages","isAIGenerated","createdAt","updatedAt") VALUES ('cmuser3jb0048slr8k3uq7j08','Altered Mental Status in a Diabetic','Endocrine','Hypoglycemia','Hard','emergency','{"age":72,"sex":"M","chiefComplaint":"Found unresponsive at home","presentingHistory":"T2DM on insulin. Missed dinner. Glucose 38 mg/dL by EMS."}','[{"question":"What is the most likely diagnosis?","answer":"Severe hypoglycemia"},{"question":"What is the immediate treatment?","answer":"IV dextrose (D50W 25g) or IM glucagon if no IV access"},{"question":"Patient awakens but becomes confused again 30 min later. Why?","answer":"Long-acting insulin still active — needs ongoing dextrose infusion"},{"question":"What is the disposition?","answer":"Admit for observation, adjust insulin regimen, diabetes education"}]',false,'2026-10-03T13:08:32.040Z','2026-10-03T13:08:32.040Z');
INSERT INTO "ClinicalCase" ("id","title","system","topic","difficulty","caseType","patientInfo","stages","isAIGenerated","createdAt","updatedAt") VALUES ('cmuser3jc0049slr8ob5tzkee','Abdominal Pain in a 25-year-old Woman','Gastrointestinal','Appendicitis','Easy','diagnostic','{"age":25,"sex":"F","chiefComplaint":"Right lower quadrant abdominal pain","presentingHistory":"Started periumbilical 12h ago, migrated to RLQ. Nausea, anorexia. LMP 2 weeks ago."}','[{"question":"What is the classic presentation?","answer":"Periumbilical pain migrating to RLQ, anorexia, nausea, low-grade fever"},{"question":"What scoring system helps risk-stratify?","answer":"Alvarado score (MANTREELS)"},{"question":"What is the imaging modality of choice in a young female?","answer":"CT with IV contrast (or US in pregnancy/peds to reduce radiation)"},{"question":"Treatment?","answer":"Appendectomy (laparoscopic preferred)"}]',false,'2026-10-03T13:08:32.040Z','2026-10-03T13:08:32.040Z');

