INSERT INTO "GroupLecture" ("id","groupId","authorId","title","description","system","topic","coverUrl","order","createdAt","updatedAt") VALUES ('cmusentbi000kq0r8qv1aqjlw','cmusent9b0000q0r8fk5irm19','cmusenrnh0000otr801tx46cg','Heart Failure — Pathophysiology & Management','Comprehensive overview of heart failure: definitions, NYHA classification, neurohormonal activation, GDMT (Guideline-Directed Medical Therapy), and acute decompensation management.','Cardiology','Heart Failure','https://images.unsplash.com/photo-1559757175-08fda86d0b0b?w=800',1,'2026-10-03T13:05:58.830Z','2026-10-03T13:05:58.830Z');
INSERT INTO "GroupLecture" ("id","groupId","authorId","title","description","system","topic","coverUrl","order","createdAt","updatedAt") VALUES ('cmusentc8000pq0r8rk1p91gg','cmusent9b0000q0r8fk5irm19','cmusenrnh0000otr801tx46cg','Acute Coronary Syndromes — STEMI vs NSTEMI','Differentiating STEMI, NSTEMI, and unstable angina. ECG interpretation, biomarkers, and the reperfusion ladder.','Cardiology','Acute Coronary Syndrome','https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=800',2,'2026-10-03T13:05:58.856Z','2026-10-03T13:05:58.856Z');
INSERT INTO "GroupLecture" ("id","groupId","authorId","title","description","system","topic","coverUrl","order","createdAt","updatedAt") VALUES ('cmusentcj000sq0r8woz7x6o5','cmusent9b0000q0r8fk5irm19','cmusenrnh0000otr801tx46cg','Antihypertensive Pharmacology','First-line antihypertensive classes, indications, contraindications, and the J-curve concept.','Pharmacology','Antihypertensives','https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=800',3,'2026-10-03T13:05:58.867Z','2026-10-03T13:05:58.867Z');
INSERT INTO "GroupLecture" ("id","groupId","authorId","title","description","system","topic","coverUrl","order","createdAt","updatedAt") VALUES ('cmusentcu000wq0r8ifevepdc','cmusenta50009q0r88izmsgs2','cmusenrpr0006otr8d2latmyn','Shock States — Recognition & Resuscitation','Differentiating distributive, cardiogenic, hypovolemic, and obstructive shock. Hemodynamic profiles and early goal-directed therapy.','Emergency Medicine','Shock','https://images.unsplash.com/photo-1666214280557-f1b5022eb634?w=800',1,'2026-10-03T13:05:58.878Z','2026-10-03T13:05:58.878Z');
INSERT INTO "GroupLecture" ("id","groupId","authorId","title","description","system","topic","coverUrl","order","createdAt","updatedAt") VALUES ('cmusentd1000yq0r86i313at3','cmusenta50009q0r88izmsgs2','cmusenrpr0006otr8d2latmyn','Acute Stroke — Time is Brain','Ischemic vs hemorrhagic stroke, NIHSS, tPA inclusion/exclusion, and thrombectomy windows.','Neurology','Stroke','https://images.unsplash.com/photo-1559757175-5700dde675bc?w=800',2,'2026-10-03T13:05:58.885Z','2026-10-03T13:05:58.885Z');

